/**
 * First-run placeholder for the generated file.
 *
 * The consumer's extension imports `./airtable-schema`, but that file only
 * exists once <SchemaObserver /> has synced, and the observer only runs once
 * the extension bundles. Writing this stub before `block run` starts breaks
 * that loop: the first bundle succeeds, the observer connects, and its first
 * save replaces the stub.
 *
 * It exports the type-level surface and an empty `airgenMeta`, and imports
 * nothing: the SDK flavor (`airgen` vs `airgen/interface`) isn't known until
 * the observer reports it, and the wrong entry breaks bundling outright.
 */

import fs from 'node:fs';

// Must start with the client's GENERATED_HEADER (generator.ts) so the stub
// passes the same header checks a real file does.
const STUB_MARKER = '// airgen placeholder: no schema synced yet.';

export const STUB_SOURCE = `// Generated by airgen — do not edit.
${STUB_MARKER}
// Written by \`npx airgen\` so your extension can bundle before <SchemaObserver />
// first connects. The observer replaces it with your base's types on its first sync.
/* eslint-disable */

export const airgenMeta = {
  "version": 3,
  "tables": {}
} as const;

export interface TableRecordMap {}

export type TableKey = keyof TableRecordMap;

export interface TableWriteMap {}

export interface TableLinkMap {}
`;

/** True for the placeholder, which carries no schema to diff against. */
export function isStub(source) {
  return typeof source === 'string' && source.split('\n', 2)[1] === STUB_MARKER;
}

/**
 * Writes the placeholder when `outPath` doesn't exist. Never overwrites: an
 * existing file, generated or not, is the consumer's.
 * @returns {boolean} whether the stub was written
 */
export function writeStubIfMissing(outPath) {
  try {
    fs.writeFileSync(outPath, STUB_SOURCE, {encoding: 'utf8', flag: 'wx'});
    return true;
  } catch (error) {
    if (error?.code === 'EEXIST') return false;
    throw error;
  }
}
